import { inferRouterInputs, inferRouterOutputs, initTRPC, experimental_standaloneMiddleware } from '@trpc/server';
import type { Overwrite } from '@trpc/server/core/internals/utils';
import { z } from 'zod';

type Equal<X, Y> = (<T>() => T extends X ? 1 : 2) extends <T>() => T extends Y ? 1 : 2 ? true : false;
function assert<T extends true>() {}

const t = initTRPC.context<{ user: string | null }>().create();
const mw = t.middleware((opts) => opts.next());
const appRouter = t.router({
  arr: t.procedure.input(z.array(z.string())).use((o) => o.next()).query(({ input }) => { const x: string[] = input; return x; }),
  tuple: t.procedure.input(z.tuple([z.string(), z.number()])).use((o) => o.next()).query(({ input }) => input),
  date: t.procedure.input(z.date()).use((o) => o.next()).query(({ input }) => input),
  map: t.procedure.input(z.map(z.string(), z.number())).use((o) => o.next()).query(({ input }) => input),
  du: t.procedure.input(z.discriminatedUnion('type', [z.object({ type: z.literal('a'), a: z.string() }), z.object({ type: z.literal('b'), b: z.number() })])).use((o) => o.next()).query(({ input }) => input),
  optObj: t.procedure.input(z.object({ a: z.string() }).optional()).use((o) => o.next()).query(({ input }) => input),
  obj: t.procedure.input(z.object({ a: z.string() })).use(mw).query(({ input }) => input),
  strOrNum: t.procedure.input(z.union([z.string(), z.number()])).use((o) => o.next()).query(({ input }) => input),
  strOrObj: t.procedure.input(z.union([z.string(), z.object({a: z.string()})])).use((o) => o.next()).query(({ input }) => input),
  unk: t.procedure.input(z.unknown()).use((o) => o.next()).query(({ input }) => input),
  anyIn: t.procedure.input(z.any()).use((o) => o.next()).query(({ input }) => input),
  voidMw: t.procedure.use(mw).query(({ input }) => input),
  ctxAny: t.procedure.use((o) => o.next({ ctx: {} as any })).query(({ ctx }) => ctx),
});
type I = inferRouterInputs<typeof appRouter>;
type O = inferRouterOutputs<typeof appRouter>;
assert<Equal<I['arr'], string[]>>();
assert<Equal<I['tuple'], [string, number]>>();
assert<Equal<I['date'], Date>>();
assert<Equal<I['map'], Map<string, number>>>();
assert<Equal<I['du'], { type: 'a'; a: string } | { type: 'b'; b: number }>>();
assert<Equal<I['optObj'], { a: string } | undefined>>();
assert<Equal<I['strOrNum'], string | number>>();
assert<Equal<I['strOrObj'], string | { a: string }>>();
assert<Equal<I['unk'], unknown>>();
type Arr = I['arr'];
//
type T1 = Overwrite<{ a: 1 }, never>;
assert<Equal<T1, { a: 1 }>>();
type T2 = Overwrite<{ a: 1 }, unknown>;
assert<Equal<T2, { a: 1 }>>();
type T3 = Overwrite<{ a: 1 }, any>;
type T4 = Overwrite<string, never>;
assert<Equal<T4, string>>();
EOF
